const DESCRIPTION = "Manage the assets makeitaquote keeps on disk, for offline use. Storage defaults to <project root>/.makeitaquote — override with MIQ_FONT_CACHE_DIR and MIQ_TWEMOJI_CACHE_DIR. Also available as `makeitaquote <command>`.";
